def top_p_sample(distribution, p):
    # already covered as cumulative probability mass in this topic
    sorted_items = sorted(distribution.items(), key=lambda item: item[1], reverse=True)

    candidates = []
    cumulative = 0.0
    for word, prob in sorted_items:
        # already covered as the p cutoff threshold in this topic
        candidates.append((word, prob))
        cumulative += prob
        if cumulative >= p:
            break

    # already covered as renormalizing top-p candidates in this topic
    total = sum(prob for _, prob in candidates)
    return {word: round(prob / total, 3) for word, prob in candidates}

sharp_distribution = {"mat": 0.7, "rug": 0.15, "floor": 0.1, "chair": 0.05}
flat_distribution = {"mat": 0.3, "rug": 0.28, "floor": 0.25, "chair": 0.17}

for name, dist in [("sharp", sharp_distribution), ("flat", flat_distribution)]:
    # already covered as adaptive candidate set size in this topic
    result = top_p_sample(dist, p=0.8)
    print(f"{name} distribution, p=0.8: {result}")
